window.docContents[168].resolve({"/5___-Representations-of-finite-groups___-Further-results/5___13___-Proof-of-the-classification-theorem-for-representations-of-___S_n___/Proof-of-Lemma-5___13___4-using-idempotent-decomposition/#Chapter5___Discussion_proof_of_Lemma5___13___4":{"contents":"Proof. Note that 1 - e is also an idempotent in A. Thus the statement immediately follows from the fact that \\operatorname{Hom}_A(A, M) \\cong M and the decomposition A = Ae \\oplus A(1 - e). \\square\n\n\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.13. Proof of the classification theorem for representations of $S_n$\u0009Proof of Lemma 5.13.4 using idempotent decomposition","header":"Proof of Lemma 5.13.4 using idempotent decomposition","id":"/5___-Representations-of-finite-groups___-Further-results/5___13___-Proof-of-the-classification-theorem-for-representations-of-___S_n___/Proof-of-Lemma-5___13___4-using-idempotent-decomposition/#Chapter5___Discussion_proof_of_Lemma5___13___4"},"/5___-Representations-of-finite-groups___-Further-results/5___2___-Algebraic-numbers-and-algebraic-integers/Algebraic-number-and-algebraic-integer-via-monic-polynomials/#Chapter5___Definition5___2___1":{"contents":"Definition 5.2.1. z \\in \\mathbb{C} is an algebraic number (respectively, an algebraic integer) if z is a root of a monic polynomial with rational (respectively, integer) coefficients.\n\n\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.2. Algebraic numbers and algebraic integers\u0009Algebraic number and algebraic integer via monic polynomials","header":"Algebraic number and algebraic integer via monic polynomials","id":"/5___-Representations-of-finite-groups___-Further-results/5___2___-Algebraic-numbers-and-algebraic-integers/Algebraic-number-and-algebraic-integer-via-monic-polynomials/#Chapter5___Definition5___2___1"}});